// The true-black recipe's keys. Shift-Command-O was Restore Previous App Launch and
// Shift-Command-M Copy Mode; each stays in the Command Palette.
[
  { "key": "cmd+shift+o", "command": "palette.newAgentChat", "args": { "harness": "codex" } },
  { "key": "cmd+shift+m", "command": "agentPane.switchModel" },
  { "key": "cmd+shift+leftbracket", "command": "prevSidebarTab" },
  { "key": "cmd+shift+rightbracket", "command": "nextSidebarTab" }
]
